const SILENT: HookResult = { continue: true, suppressOutput: true };

vi.mock('../../pretool/bash/sync-bash-dispatcher.js', () => ({ syncBashDispatcher: vi.fn(() => SILENT) }));
vi.mock('../../pretool/write-edit/sync-write-edit-dispatcher.js', () => ({ syncWriteEditDispatcher: vi.fn(() => SILENT) }));
vi.mock('../../pretool/read/tldr-summary.js', () => ({ tldrSummary: vi.fn(() => SILENT) }));
vi.mock('../../pretool/task/sync-task-dispatcher.js', () => ({ syncTaskDispatcher: vi.fn(() => SILENT) }));
vi.mock('../../pretool/task/route-observer.js', () => ({ routeObserver: vi.fn(() => SILENT) }));
vi.mock('../../pretool/skill/skill-tracker.js', () => ({ skillTracker: vi.fn(() => SILENT) }));
