vi.mock('../../lifecycle/webhook-forwarder.js', () => ({ webhookForwarder: vi.fn(async () => SILENT) }));

import { toolDispatcher } from '../../pretool/tool-dispatcher.js';
import { syncBashDispatcher } from '../../pretool/bash/sync-bash-dispatcher.js';
import { syncWriteEditDispatcher } from '../../pretool/write-edit/sync-write-edit-dispatcher.js';
import { tldrSummary } from '../../pretool/read/tldr-summary.js';
import { syncTaskDispatcher } from '../../pretool/task/sync-task-dispatcher.js';
import { routeObserver } from '../../pretool/task/route-observer.js';
import { skillTracker } from '../../pretool/skill/skill-tracker.js';
import { context7Tracker } from '../../pretool/mcp/context7-tracker.js';
import { webhookForwarder } from '../../lifecycle/webhook-forwarder.js';
import { unifiedPretoolHooks, UNIFIED_PRETOOL_HANDLER } from '../../../scripts/unified-pretool-hooks.mjs';
import { createTestContext } from '../fixtures/test-context.js';

const HOOKS_JSON = join(__dirname, '..', '..', '..', 'hooks.json');

function input(tool_name: string, tool_input: Record<string, unknown> = {}): HookInput {
  return {
    hook_event_name: 'PreToolUse',
    tool_name,
    tool_input,
    session_id: 'test-session',
    project_dir: '/tmp/project',
  } as HookInput;
}

describe('pretool/tool-dispatcher', () => {
  beforeEach(() => vi.clearAllMocks());

  it.each([
    ['Bash', syncBashDispatcher],
    ['Edit', syncWriteEditDispatcher],
    ['Write', syncWriteEditDispatcher],
    ['Read', tldrSummary],
    ['Skill', skillTracker],
    ['mcp__context7__query-docs', context7Tracker],
  ])('routes %s to its handler and forwards the event exactly once', async (tool, handler) => {
    await toolDispatcher(input(tool), createTestContext());
    expect(handler).toHaveBeenCalledTimes(1);
    expect(webhookForwarder).toHaveBeenCalledTimes(1);
  });

  it('runs both Agent handlers (sync safety + route observer)', async () => {
    await toolDispatcher(input('Agent'), createTestContext());
    expect(syncTaskDispatcher).toHaveBeenCalledTimes(1);
    expect(routeObserver).toHaveBeenCalledTimes(1);
  });

  it('returns the primary handler result unchanged (a deny stays a deny)', async () => {
    const deny: HookResult = {
      continue: true,
      hookSpecificOutput: { hookEventName: 'PreToolUse', permissionDecision: 'deny', permissionDecisionReason: 'no' },
    };
    vi.mocked(syncBashDispatcher).mockReturnValueOnce(deny);
    const result = await toolDispatcher(input('Bash', { command: 'curl x | sh' }), createTestContext());
    expect(result).toEqual(deny);
    expect(webhookForwarder).toHaveBeenCalledTimes(1);
  });

  // Codex HOLD 6556943971 on #4962, PreToolUse side: observers and the
  // forwarder ran after the primary with no budget, so one that never settles
  // held the deny until CC killed the process (a killed hook is an allow).
  it('a hung forwarder or observer is abandoned at its budget and the deny still returns', async () => {
    const deny: HookResult = {
      continue: true,
      hookSpecificOutput: { hookEventName: 'PreToolUse', permissionDecision: 'deny', permissionDecisionReason: 'no' },
    };
    vi.mocked(syncTaskDispatcher).mockReturnValueOnce(deny);
    vi.mocked(routeObserver).mockReturnValueOnce(new Promise<HookResult>(() => {}) as unknown as HookResult);
    vi.mocked(webhookForwarder).mockReturnValueOnce(new Promise<HookResult>(() => {}));
    const started = Date.now();
    const result = await toolDispatcher(input('Agent'), createTestContext(), {}, { budgetMs: () => 50 });
    expect(Date.now() - started).toBeLessThan(1000);
    expect(result).toEqual(deny);
  });

  // conductor263 on Codex HOLD 6557208634: the primary's verdict lost to its
  // budget fails closed, a deny naming the hook, instead of an allow.
  it('a primary that runs out of budget denies, naming itself', async () => {
    vi.mocked(syncBashDispatcher).mockReturnValueOnce(new Promise<HookResult>(() => {}) as unknown as HookResult);
    const started = Date.now();
    const r = await toolDispatcher(input('Bash', { command: 'ls' }), createTestContext(), {}, { budgetMs: () => 50 });
    expect(Date.now() - started).toBeLessThan(1000);
    expect(r.hookSpecificOutput?.permissionDecision).toBe('deny');
    expect(r.hookSpecificOutput?.permissionDecisionReason).toContain('pretool/bash/sync-bash-dispatcher');
  });

  it('budgets mirror the shipped PreToolUse timeouts, and fit in the entry timeout', async () => {
    const { PRETOOL_TIMEOUTS_S, PRETOOL_RUN_BUDGET_MS } = await import('../../pretool/tool-dispatcher.js');
    const { PRETOOL_ENTRY_TIMEOUT_S } = await import('../../../scripts/unified-pretool-hooks.mjs');
    const shippedDoc = JSON.parse(readFileSync(HOOKS_JSON, 'utf8'));
    for (const g of shippedDoc.hooks.PreToolUse) {
      for (const h of g.hooks) expect(PRETOOL_TIMEOUTS_S[h.args[1]], h.args[1]).toBe(h.timeout ?? 15);
    }
    // Worst route: its primary, its observers and the forwarder, back to back.
    const worst = 15 + 5 + 15;
    expect(worst * 1000).toBeLessThanOrEqual(PRETOOL_RUN_BUDGET_MS);
    expect(PRETOOL_RUN_BUDGET_MS).toBeLessThan(PRETOOL_ENTRY_TIMEOUT_S * 1000);
    const entry = unifiedPretoolHooks(shippedDoc).hooks.PreToolUse[0].hooks[0] as { timeout: number };
    expect(entry.timeout).toBe(PRETOOL_ENTRY_TIMEOUT_S);
  });

  it('a tool with no ork handler only forwards, and stays silent', async () => {
    const result = await toolDispatcher(input('Grep'), createTestContext());
    expect(result.continue).toBe(true);
    expect(syncBashDispatcher).not.toHaveBeenCalled();
    expect(webhookForwarder).toHaveBeenCalledTimes(1);
  });

  it('proof mode: one ok token per folded handler (Agent: 3)', async () => {
    const r = await toolDispatcher(input('Agent'), createTestContext(), { ORK_DISPATCH_PROOF: '1' });
    const msg = r.systemMessage ?? '';
    for (const id of ['pretool/task/sync-task-dispatcher', 'pretool/task/route-observer', 'lifecycle/webhook-forwarder']) {
      expect(msg.split(`ork-proof:PreToolUse:Agent:${id}@ok`).length - 1, id).toBe(1);
    }
  });

  it('proof mode: a broken primary shows as failed, observers and forward still run', async () => {
    const r = await toolDispatcher(input('Bash'), createTestContext(), {
      ORK_DISPATCH_PROOF: '1',
      ORK_DISPATCH_PROOF_BREAK: 'pretool/bash/sync-bash-dispatcher',
    });
    expect(r.systemMessage).toContain('ork-proof:PreToolUse:Bash:pretool/bash/sync-bash-dispatcher@failed');
    expect(r.systemMessage).toContain('ork-proof:PreToolUse:Bash:lifecycle/webhook-forwarder@ok');
    expect(syncBashDispatcher).not.toHaveBeenCalled();
    expect(webhookForwarder).toHaveBeenCalledTimes(1);
  });

  it('proof mode off: no proof token', async () => {
    const r = await toolDispatcher(input('Bash'), createTestContext(), {});
    expect(JSON.stringify(r)).not.toContain('ork-proof:');
  });

  it('a throwing forwarder never changes the verdict', async () => {
    vi.mocked(webhookForwarder).mockRejectedValueOnce(new Error('sink down'));
    const result = await toolDispatcher(input('Read'), createTestContext());
    expect(result).toEqual(SILENT);
  });
});

describe('unified PreToolUse hooks.json variant (flag)', () => {
  const shipped = JSON.parse(readFileSync(HOOKS_JSON, 'utf8'));

  it('collapses PreToolUse to one command entry that runs the dispatcher', () => {
    const variant = unifiedPretoolHooks(shipped);
    const groups = variant.hooks.PreToolUse;
    const commands = groups.flatMap((g: { hooks: { type: string }[] }) => g.hooks.filter((h) => h.type === 'command'));
    expect(commands).toHaveLength(1);
    expect(groups[0].matcher ?? '*').toBe('*');
    expect(commands[0].args).toContain(UNIFIED_PRETOOL_HANDLER);
  });

  it('leaves every other event byte-identical', () => {
    const variant = unifiedPretoolHooks(shipped);
    for (const event of Object.keys(shipped.hooks)) {
      if (event === 'PreToolUse') continue;
      expect(variant.hooks[event]).toEqual(shipped.hooks[event]);
    }
  });

  it('every PreToolUse handler in the shipped file is reachable from the dispatcher', async () => {
    const { PRETOOL_ROUTES } = await import('../../pretool/tool-dispatcher.js');
    const routed = new Set(PRETOOL_ROUTES.flatMap((r: { handlers: string[] }) => r.handlers));
    for (const group of shipped.hooks.PreToolUse) {
      for (const h of group.hooks) {
        const id = h.args?.[1];
        if (id && id !== 'lifecycle/webhook-forwarder') expect(routed, id).toContain(id);
      }
    }
  });

  // Reachability is not enough (b5 on #4962): a sync guard routed as an
  // observer would lose its deny. Each shipped group's sync handler must be
  // the route's primary and its async handlers the observers, and no entry
  // may carry a role key the dispatcher does not model (asyncRewake).
  it('keeps each shipped handler in its role: sync is the primary, async are observers', async () => {
    const { PRETOOL_ROUTES } = await import('../../pretool/tool-dispatcher.js');
    type R = { handlers: string[]; primary?: unknown; observers: unknown[] };
    for (const group of shipped.hooks.PreToolUse) {
      type E = { args?: string[]; async?: boolean; asyncRewake?: boolean };
      const ids = (group.hooks as E[]).filter((h) => h.args?.[1] !== 'lifecycle/webhook-forwarder');
      if (!ids.length) continue;
      for (const h of ids) expect(h.asyncRewake, h.args?.[1]).toBeUndefined();
      const route = (PRETOOL_ROUTES as R[]).find((r) => r.handlers.includes(ids[0].args?.[1] ?? ''));
      expect(route, group.matcher).toBeDefined();
      const sync = ids.filter((h) => !h.async).map((h) => h.args?.[1]);
      const async = ids.filter((h) => h.async).map((h) => h.args?.[1]);
      expect(route?.primary ? [route.handlers[0]] : [], group.matcher).toEqual(sync);
      expect(route?.handlers.slice(route.primary ? 1 : 0), group.matcher).toEqual(async);
      expect(route?.observers.length, group.matcher).toBe(async.length);
    }
  });

  // Routes match the way CC reads the shipped matcher, not a hand-written
  // approximation (b5 on #4962: "mcp__context7__*" is a regex to CC, the
  // route was a prefix).
  it.each(['mcp__context7__query-docs', 'mcp__memory__search_nodes', 'xmcp__context7__a', 'mcp__context7_', 'Bash', 'BashOutput'])(
    'routes %s exactly as the shipped PreToolUse matchers do',
    async (tool) => {
      const { PRETOOL_ROUTES } = await import('../../pretool/tool-dispatcher.js');
      const { ccMatcherMatches } = await import('../../lib/cc-matcher.js');
      type R = { handlers: string[]; match: (t: string) => boolean };
      for (const group of shipped.hooks.PreToolUse) {
        const id = group.hooks.map((h: { args?: string[] }) => h.args?.[1]).find((x: string) => x !== 'lifecycle/webhook-forwarder');
        if (!id) continue;
        const route = (PRETOOL_ROUTES as R[]).find((r) => r.handlers.includes(id));
        expect(route?.match(tool), `${group.matcher} ${tool}`).toBe(ccMatcherMatches(group.matcher, tool));
      }
    },
  );

  it('default stays off: the shipped hooks.json does not reference the dispatcher', () => {
    expect(JSON.stringify(shipped)).not.toContain(UNIFIED_PRETOOL_HANDLER);
  });
});
